test("should reconnect after cross-origin navigation without leaking input or cleanup errors", async ({ page }) => {
  const errors: string[] = [];
  page.on("pageerror", (error) => errors.push(error.message));
  // Fulfilled locally: exercise real origin isolation without a remote server.
  const external = "https://arcade-input.invalid/fixture";
  await page.route(`${external}*`, (route) => route.fulfill({ contentType: "text/html", body: inputFixture }));
  await openPlayer(page);
  await showControls(page);
  const iframe = page.getByTestId("game-iframe");
  const originalSrc = await iframe.getAttribute("src");
  expect(originalSrc).not.toBeNull();
  const controls = page.getByRole("region", { name: "Game controls", exact: true });
  const right = controls.getByRole("button", { name: "Move right", exact: true });
  const action = controls.getByRole("button", { name: "A (Z key)", exact: true });

  for (let round = 0; round < 2; round++) {
    await right.dispatchEvent("pointerdown", { pointerId: 901, pointerType: "mouse", button: 0, buttons: 1 });
    await expect.poll(() => recordedKeys(page)).toEqual([
      { type: "keydown", code: "ArrowRight", key: "ArrowRight" },
    ]);
    await action.focus();
    await page.keyboard.down("Enter");
    await iframe.evaluate((element, src) => { (element as HTMLIFrameElement).src = src; }, `${external}?round=${round}`);
    await expect.poll(() => page.frames().some((frame) => frame.url() === `${external}?round=${round}`)).toBe(true);
    await expect.poll(() => iframe.evaluate((element) => (element as HTMLIFrameElement).contentDocument === null)).toBe(true);
    await page.keyboard.up("Enter");
    await right.dispatchEvent("pointercancel", { pointerId: 901, pointerType: "mouse" });
    await right.click();
    expect(await recordedKeys(page)).toEqual([]);

    await iframe.evaluate((element, src) => { (element as HTMLIFrameElement).src = src; }, originalSrc!);
    await expect(page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("#key-events")).toHaveText("[]");
    await right.dispatchEvent("pointercancel", { pointerId: 901, pointerType: "mouse" });
    expect(await recordedKeys(page)).toEqual([]);
    await right.click();
    await expect.poll(() => recordedKeys(page)).toEqual([
      { type: "keydown", code: "ArrowRight", key: "ArrowRight" },
      { type: "keyup", code: "ArrowRight", key: "ArrowRight" },
    ]);
    // Reconnected document listeners must still interrupt an owned key.
    await right.dispatchEvent("pointerdown", { pointerId: 902, pointerType: "mouse", button: 0, buttons: 1 });
    await page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("body").evaluate(() => window.dispatchEvent(new Event("blur")));
    await right.dispatchEvent("pointercancel", { pointerId: 902, pointerType: "mouse" });
    await expect.poll(() => recordedKeys(page)).toEqual([
      { type: "keydown", code: "ArrowRight", key: "ArrowRight" },
      { type: "keyup", code: "ArrowRight", key: "ArrowRight" },
      { type: "keydown", code: "ArrowRight", key: "ArrowRight" },
      { type: "keyup", code: "ArrowRight", key: "ArrowRight" },
    ]);
    await page.getByRole("button", { name: "Back to games", exact: true }).click();
    await expect(page.getByTestId("game-player")).toBeHidden();
    await page.getByRole("button", { name: `Play ${gameTitle}`, exact: true }).click();
    await expect(page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("#key-events")).toHaveText("[]");
    await showControls(page);
  }
  expect(errors).toEqual([]);
});

 test("should cancel a diagonal synchronously during its first keydown after reload", async ({ page }) => {
  await openPlayer(page);
  await showControls(page);
  const iframe = page.getByTestId("game-iframe");
  await iframe.evaluate((element) => new Promise<void>((resolve) => {
    element.addEventListener("load", () => resolve(), { once: true });
    const frame = element as HTMLIFrameElement;
    frame.contentWindow!.location.reload();
  }));
  await expect(page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("#key-events")).toHaveText("[]");
  await page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("body").evaluate(() => {
    window.addEventListener("keydown", () => window.dispatchEvent(new Event("blur")), { once: true });
  });
  const diagonal = page.getByRole("region", { name: "Game controls", exact: true })
    .getByRole("button", { name: "Move up-right", exact: true });
  await diagonal.dispatchEvent("pointerdown", { pointerId: 903, pointerType: "mouse", button: 0, buttons: 1 });
  await diagonal.dispatchEvent("pointercancel", { pointerId: 903, pointerType: "mouse" });
  await expect.poll(() => recordedKeys(page)).toEqual([
    { type: "keydown", code: "ArrowUp", key: "ArrowUp" },
    { type: "keyup", code: "ArrowUp", key: "ArrowUp" },
  ]);
});

for (const source of ["host", "iframe"] as const) {
  test(`should discover ${source} touch after reopening and remember it across another opening`, async ({ page }) => {
    await page.addInitScript(() => {
      const matchMedia = window.matchMedia.bind(window);
      window.matchMedia = (query) => {
        const result = matchMedia(query);
        if (query === "(pointer: coarse)") Object.defineProperty(result, "matches", { value: false });
        return result;
      };
    });
    await openPlayer(page);
    const controls = page.getByRole("region", { name: "Game controls", exact: true });
    await expect(controls).toBeHidden();
    await page.getByRole("button", { name: "Back to games", exact: true }).click();
    await expect(page.getByTestId("game-player")).toBeHidden();
    await page.getByRole("button", { name: `Play ${gameTitle}`, exact: true }).click();
    await expect(page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("#key-events")).toHaveText("[]");
    await expect(controls).toBeHidden();
    const surface = source === "host" ? page.locator("html")
      : page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("html");
    await surface.evaluate((element) => element.dispatchEvent(new PointerEvent("pointerdown", { pointerType: "touch", bubbles: true })));
    await expect(controls).toBeVisible();
    await page.getByRole("button", { name: "Hide controls", exact: true }).click();
    await surface.evaluate((element) => element.dispatchEvent(new PointerEvent("pointerdown", { pointerType: "touch", bubbles: true })));
    await expect(controls).toBeHidden();
    await page.getByRole("button", { name: "Back to games", exact: true }).click();
    await expect(page.getByTestId("game-player")).toBeHidden();
    await page.getByRole("button", { name: `Play ${gameTitle}`, exact: true }).click();
    await expect(controls).toBeVisible();
  });
}

